class InitializationOrder {
    // 1. Declared First -> Initialized First
    int i;
    // 2. Declared Second -> Initialized Second
    int j;

public:
    // Initializer list order: j(val) then i(j)
    // Actual order: i is initialized, then j is initialized.
    //
    // When 'i' is initialized, 'j' holds an
    // indeterminate value (potential UB if read).
    InitializationOrder(int val)
      : j(val), i(j) {}
};

// Rule: Member initialization follows declaration order.
